import{_ as o}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as r,o as e,af as n}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"Grok Connectors","description":"","frontmatter":{},"headers":[],"relativePath":"zh/products/ai-coding/grok/grok-connectors.md","filePath":"zh/products/ai-coding/grok/grok-connectors.md","lastUpdated":1787110548000}'),a={name:"zh/products/ai-coding/grok/grok-connectors.md"};function s(c,t,d,l,i,h){return e(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="grok-connectors" tabindex="-1">Grok Connectors <a class="header-anchor" href="#grok-connectors" aria-label="Permalink to &quot;Grok Connectors&quot;">​</a></h1><blockquote><p>官方定义（<a href="https://docs.x.ai/grok/connectors" target="_blank" rel="noreferrer">docs.x.ai/grok/connectors</a>）： &quot;Connectors are available to all Grok users and let Grok access your external tools and data sources directly within a conversation. Search your email, browse files in cloud storage, check your calendar, and more without leaving the chat.&quot;</p><p>对位 <a href="./../claude/connectors.html">Claude Connectors</a>。本页是<strong>聊天</strong>里的 connector 目录。不是 Grok Build 的 MCP（<code>grok mcp add</code>），也不是 Grok Bot 的 Plugins。</p></blockquote><h2 id="目标与非目标" tabindex="-1">目标与非目标 <a class="header-anchor" href="#目标与非目标" aria-label="Permalink to &quot;目标与非目标&quot;">​</a></h2><p><strong>写给谁：</strong> 想在 grok.com 对话里读邮件、Drive、日历，或接自定义 MCP 的人。</p><p><strong>目标：</strong> 列出官方三种类型、内置表、Business 管理员门槛、本地隧道规则。</p><p><strong>非目标：</strong> 再写一遍 MCP 协议教程、臆造目录条目，或 Grok Build 的 <code>[mcp_servers]</code> 配置（那是 <a href="./grok-cli.html">grok-cli.md</a> / <a href="./grok-cookbook.html">cookbook</a>）。</p><h2 id="三种类型" tabindex="-1">三种类型 <a class="header-anchor" href="#三种类型" aria-label="Permalink to &quot;三种类型&quot;">​</a></h2><p><a href="https://docs.x.ai/grok/connectors" target="_blank" rel="noreferrer">connectors</a>：</p><table tabindex="0"><thead><tr><th>类型</th><th>谁维护</th><th>怎么加</th></tr></thead><tbody><tr><td><strong>Built-in</strong></td><td>xAI，原生 OAuth</td><td><a href="https://grok.com/connectors" target="_blank" rel="noreferrer">grok.com/connectors</a> → <strong>New Connector</strong> → 选服务 → OAuth</td></tr><tr><td><strong>Catalog</strong></td><td>更多第三方服务的预配置 OAuth</td><td>同一页浏览目录。官方文档没有冻死完整名单</td></tr><tr><td><strong>Custom MCP</strong></td><td>你（公网 MCP 服务器）</td><td><strong>New Connector</strong> → <strong>Custom</strong> → MCP 服务器 URL + 认证</td></tr></tbody></table><p>连上之后，问题跟该服务相关时，Grok 可以自动调用它的工具。本页没有写「每个对话再勾选一次」。</p><h3 id="内置-connectors" tabindex="-1">内置 connectors <a class="header-anchor" href="#内置-connectors" aria-label="Permalink to &quot;内置 connectors&quot;">​</a></h3><p>官方表（<a href="https://docs.x.ai/grok/connectors" target="_blank" rel="noreferrer">connectors</a>）：</p><table tabindex="0"><thead><tr><th>Connector</th><th>连什么</th></tr></thead><tbody><tr><td><strong>Gmail &amp; Google Calendar</strong></td><td>Gmail 邮件与 Google Calendar 日程</td></tr><tr><td><strong>Google Drive</strong></td><td>Google Drive 文件、Docs、Sheets、Slides</td></tr><tr><td><strong>OneDrive</strong></td><td>Microsoft OneDrive 个人存储</td></tr><tr><td><strong>Outlook Mail &amp; Calendar</strong></td><td>Outlook 邮件与日历</td></tr><tr><td><strong>Microsoft Teams</strong></td><td>Microsoft Teams 消息、频道、聊天</td></tr><tr><td><strong>SharePoint</strong></td><td>Microsoft SharePoint 站点与文档库</td></tr><tr><td><strong>Salesforce</strong></td><td>Salesforce CRM — 浏览对象、查询、创建与更新记录</td></tr></tbody></table><h3 id="自定义-mcp-connectors" tabindex="-1">自定义 MCP connectors <a class="header-anchor" href="#自定义-mcp-connectors" aria-label="Permalink to &quot;自定义 MCP connectors&quot;">​</a></h3><p>官方能力（<a href="https://docs.x.ai/grok/connectors" target="_blank" rel="noreferrer">connectors</a>）：</p><ul><li>把内部 API、数据库或 SaaS 工具暴露给 Grok。</li><li>自定义工具的 schema 与逻辑。</li><li>认证和访问控制放在你自己的基础设施上。</li></ul><p>MCP 服务器<strong>必须能从公网访问</strong>。<code>localhost</code> 与 RFC1918 地址（<code>127.0.0.1</code>、<code>10.x</code>、<code>172.16.x</code>、<code>192.168.x</code>）会被<strong>拒绝</strong>（<a href="https://docs.x.ai/grok/connectors/custom-mcp-tunneling" target="_blank" rel="noreferrer">custom-mcp-tunneling</a>）。</p><p>该页的隧道形状：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Grok ──► https://your-tunnel.example.com ──► tunnel provider ──► localhost:3001</span></span></code></pre></div><p>官方举例：<strong>ngrok</strong>（<code>ngrok http 3001</code>）和 <strong>Cloudflare Tunnel</strong>（<code>cloudflared tunnel --url http://localhost:3001</code>）。Cloudflare <strong>quick</strong> tunnel <strong>不支持 SSE</strong>——服务器走 SSE 就用 ngrok。Streamable HTTP 在 Cloudflare 上没问题。</p><p>免费档隧道 URL 多半是临时的。重启 → 新 URL → 在 Grok 里删掉旧 connector 再加新的。本地服务器要一直开着；Grok 按需调用。</p><h2 id="business-与-enterprise" tabindex="-1">Business 与 Enterprise <a class="header-anchor" href="#business-与-enterprise" aria-label="Permalink to &quot;Business 与 Enterprise&quot;">​</a></h2><p><a href="https://docs.x.ai/grok/connectors" target="_blank" rel="noreferrer">connectors</a>：</p><blockquote><p>For Grok Business and Enterprise users, a team admin must first provision a connector in the <a href="https://docs.x.ai/grok/connector-management" target="_blank" rel="noreferrer">cloud console</a> before it is available to members of the organization.</p></blockquote><p>管理员路径（<a href="https://docs.x.ai/grok/connector-management" target="_blank" rel="noreferrer">connector-management</a>）：<a href="https://console.x.ai" target="_blank" rel="noreferrer">console.x.ai</a> → 团队 → <strong>Grok Business → Connectors</strong>。增删需要 <strong>Team Read-Write</strong>。</p><ol><li><strong>+ Add Connector</strong> 从目录选，或 <strong>Other</strong> + MCP URL。</li><li>部分 Microsoft / Salesforce 还要管理员同意。管理页指向 SharePoint、OneDrive、Salesforce 的专项指南。</li><li>管理员开通之后，成员仍要在 <a href="https://grok.com/connectors" target="_blank" rel="noreferrer">grok.com/connectors</a> 连接<strong>自己的</strong>账号。</li><li><strong>Remove</strong> 对全队删除；与该 connector 相关的索引数据可能被清掉。</li></ol><p>个人（非 Business）账号没有管理员这一步。</p><h2 id="不是这些-connectors" tabindex="-1">不是这些 connectors <a class="header-anchor" href="#不是这些-connectors" aria-label="Permalink to &quot;不是这些 connectors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>看起来像</th><th>其实是</th></tr></thead><tbody><tr><td>Grok 聊天 Connectors</td><td>本页</td></tr><tr><td>Grok Build MCP</td><td><code>grok mcp add</code> / <code>~/.grok/config.toml</code> 的 <code>[mcp_servers]</code> — 工具名带 <code>&lt;server&gt;__&lt;tool&gt;</code></td></tr><tr><td>Grok Bot「Plugins」</td><td><a href="./grok-bot.html">Grok Bot</a> Settings → Plugins；<code>@</code> 挂上</td></tr><tr><td>Voice API 的 <code>mcp</code> 工具</td><td><code>wss://api.x.ai/v1/realtime</code> 上的服务端 MCP（<a href="./grok-voice.html">Voice</a>）</td></tr></tbody></table><h2 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to &quot;常见陷阱&quot;">​</a></h2><ul><li>自定义 connector 填 <code>http://localhost:3001</code>。官方会拒。</li><li>Business 成员在管理员开通之前就指望看到 Gmail。</li><li>把 Grok Build 的 MCP 配置抄到 grok.com。产品不同，宿主不同。</li><li>SSE MCP 服务器走 Cloudflare quick tunnel。</li></ul><h2 id="官方文档" tabindex="-1">官方文档 <a class="header-anchor" href="#官方文档" aria-label="Permalink to &quot;官方文档&quot;">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>用来干什么</th></tr></thead><tbody><tr><td><a href="https://docs.x.ai/grok/connectors" target="_blank" rel="noreferrer">docs.x.ai/grok/connectors</a></td><td>三种类型 + 内置表</td></tr><tr><td><a href="https://docs.x.ai/grok/connector-management" target="_blank" rel="noreferrer">docs.x.ai/grok/connector-management</a></td><td>Business 管理员开通</td></tr><tr><td><a href="https://docs.x.ai/grok/connectors/custom-mcp-tunneling" target="_blank" rel="noreferrer">docs.x.ai/grok/connectors/custom-mcp-tunneling</a></td><td>公网 URL / 隧道</td></tr><tr><td><a href="https://grok.com/connectors" target="_blank" rel="noreferrer">grok.com/connectors</a></td><td>用户侧添加 / 连接</td></tr><tr><td><a href="https://docs.x.ai/grok/overview" target="_blank" rel="noreferrer">docs.x.ai/grok/overview</a></td><td>聊天能力里的 Connectors</td></tr></tbody></table><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./grok-chat.html">Grok 聊天</a></li><li><a href="./grok-business.html">Grok Business</a> — 必须先由管理员开通</li><li><a href="./grok-cookbook.html">Grok Build cookbook</a> — CLI MCP，不是这个</li><li><a href="./grok-bot.html">Grok Bot</a></li><li><a href="./">Grok 学习地图</a></li></ul>',35)])])}const f=o(a,[["render",s]]);export{m as __pageData,f as default};
